// swift-tools-version: 5.9
// The swift-tools-version declares the minimum version of Swift required to build this package.

import PackageDescription

let package = Package(
    name: "sqflite_sqlcipher",
    platforms: [
        .iOS("12.0"),
        .macOS("10.13")
    ],
    products: [
        // If the plugin name contains "_", replace with "-" for the library name.
        .library(name: "sqflite-sqlcipher", targets: ["sqflite_sqlcipher"])
    ],
    dependencies: [
        // Flutter framework, generated by the Flutter tool during the build (Flutter 3.41+).
        .package(name: "FlutterFramework", path: "../FlutterFramework")
    ],
    targets: [
        .target(
            name: "sqflite_sqlcipher",
            dependencies: [
                .product(name: "FlutterFramework", package: "FlutterFramework"),
                // Source-built SQLCipher amalgamation, linked statically (see target below).
                "SQLCipher"
            ],
            exclude: [
                "fmdb/LICENSE"
            ],
            resources: [
                .process("Resources")
            ],
            cSettings: [
                .headerSearchPath("include/sqflite_sqlcipher"),
                // Vendored FMDB sources (FMDB's own SPM SQLCipher support is unreleased).
                .headerSearchPath("fmdb"),
                // Required so FMDB/SQLCipher expose the codec API (sqlite3_key, etc.).
                .define("SQLITE_HAS_CODEC")
            ]
        ),
        // SQLCipher built from the vendored amalgamation (4.10.0) as a static C target.
        // Static linkage makes the sqlite3_* symbols *defined* in the final app binary,
        // so they can never be shadowed by the system /usr/lib/libsqlite3.dylib — the
        // exact property the old CocoaPods static-pod path relied on, and which the
        // prebuilt SQLCipher.swift *dynamic* xcframework could not guarantee.
        //
        // The build flags mirror the CocoaPods `SQLCipher` 4.10.0 podspec verbatim so the
        // on-disk database format and CommonCrypto crypto backend stay byte-compatible
        // across the SPM and CocoaPods builds (see cross_version_test/).
        .target(
            name: "SQLCipher",
            exclude: [
                "LICENSE.txt"
            ],
            cSettings: [
                // SQLite's amalgamation auto-defines NDEBUG (disabling its internal
                // asserts) when neither NDEBUG nor SQLITE_DEBUG is set — the configuration
                // every SQLite/SQLCipher distribution (incl. the CocoaPods pod) ships with.
                // SwiftPM compiles C targets with `-fmodules`, under which that internal
                // auto-define fails to reach the assert sites in DEBUG builds, leaving the
                // asserts active while the `#ifdef SQLITE_DEBUG`-only helper prototypes
                // (sqlite3BtreeHoldsAllMutexes, etc.) stay absent — an implicit-declaration
                // error. Defining NDEBUG here forces that intended state explicitly.
                .define("NDEBUG"),
                .define("SQLITE_HAS_CODEC"),
                .define("SQLITE_TEMP_STORE", to: "2"),
                .define("SQLITE_SOUNDEX"),
                .define("SQLITE_THREADSAFE"),
                .define("SQLITE_ENABLE_RTREE"),
                .define("SQLITE_ENABLE_STAT3"),
                .define("SQLITE_ENABLE_STAT4"),
                .define("SQLITE_ENABLE_COLUMN_METADATA"),
                .define("SQLITE_ENABLE_MEMORY_MANAGEMENT"),
                .define("SQLITE_ENABLE_LOAD_EXTENSION"),
                .define("SQLITE_ENABLE_FTS4"),
                .define("SQLITE_ENABLE_FTS4_UNICODE61"),
                .define("SQLITE_ENABLE_FTS3_PARENTHESIS"),
                .define("SQLITE_ENABLE_UNLOCK_NOTIFY"),
                .define("SQLITE_ENABLE_JSON1"),
                .define("SQLITE_ENABLE_FTS5"),
                // Select the Apple CommonCrypto backend (same as the pod) — no OpenSSL.
                .define("SQLCIPHER_CRYPTO_CC"),
                .define("HAVE_USLEEP", to: "1"),
                .define("SQLITE_MAX_VARIABLE_NUMBER", to: "99999"),
                .define("SQLITE_EXTRA_INIT", to: "sqlcipher_extra_init"),
                .define("SQLITE_EXTRA_SHUTDOWN", to: "sqlcipher_extra_shutdown")
            ],
            linkerSettings: [
                // CommonCrypto random bytes come from Security.framework; Foundation is
                // pulled in by the SQLCipher CommonCrypto provider.
                .linkedFramework("Foundation"),
                .linkedFramework("Security")
            ]
        )
    ]
)
